    const onBack = mock();
    render(<WorldSelect profile={PROFILE} onPlay={mock()} onBack={onBack} />);
    await user.click(screen.getByTestId("back-to-profiles"));
    expect(onBack).toHaveBeenCalledTimes(1);
  });
});

