1	import { useState } from "react";
2	import PixelImg from "@/components/game/PixelImg";
3	import CreateProfileForm from "@/components/menu/CreateProfileForm";
4	import MenuScreen from "@/components/menu/MenuScreen";
5	import { createProfile, deleteProfile, MAX_PROFILE_NAME, readProfiles, renameProfile } from "@/lib/game/profiles";
6	import { skinPortraitUrl } from "@/lib/ui/sprites";
7	import { deleteWorldsForProfile, worldsForProfile } from "@/lib/game/worlds";
8	
9	type ProfileSelectProps = {
10	  /** Enter a profile: select it and show its worlds. */
11	  onPlay: (profileId: string) => void;
12	};
13	
14	/** The top menu: pick a player profile, or create / rename / delete one. */
15	export default function ProfileSelect({ onPlay }: ProfileSelectProps) {
16	  const [creating, setCreating] = useState(false);
17	  const [editingId, setEditingId] = useState<string | null>(null);
18	  const [editName, setEditName] = useState("");
19	  const [confirmingDeleteId, setConfirmingDeleteId] = useState<string | null>(null);
20	
21	  const { profiles } = readProfiles();
22	  // With no profiles (first run, or the last one was just deleted) there is
23	  // nothing to select, so open straight into the create form with no Cancel.
24	  const firstRun = profiles.length === 0;
25	
26	  if (creating || firstRun) {
27	    return (
28	      <MenuScreen title={firstRun ? "Create Your Profile" : "New Profile"}>
29	        <CreateProfileForm
30	          onCreate={(name, skinId) => {
31	            const profile = createProfile(name, skinId);
32	            setCreating(false);
33	            onPlay(profile.id); // straight into the new profile's (empty) world list
34	          }}
35	          onCancel={firstRun ? undefined : () => setCreating(false)}
36	        />
37	      </MenuScreen>
38	    );
39	  }
40	
41	  return (
42	    <MenuScreen title="Select Profile">
43	      <ul className="menu-list">
44	        {profiles.map((profile) => (
45	          <li key={profile.id} className="menu-card">
46	            {editingId === profile.id ? (
47	              <form
48	                className="menu-rename"
49	                onSubmit={(event) => {
50	                  event.preventDefault();
51	                  renameProfile(profile.id, editName);
52	                  setEditingId(null); // re-render re-reads the manifest
53	                }}
54	              >
55	                <input
56	                  className="menu-input"
57	                  value={editName}
58	                  maxLength={MAX_PROFILE_NAME}
59	                  autoFocus
60	                  aria-label="Rename profile"
61	                  onChange={(event) => setEditName(event.target.value)}
62	                />
63	                <button type="submit" className="mc-button">
64	                  Save
65	                </button>
66	                <button type="button" className="mc-button" onClick={() => setEditingId(null)}>
67	                  Cancel
68	                </button>
69	              </form>
70	            ) : confirmingDeleteId === profile.id ? (
71	              <div className="menu-confirm">
72	                <span>Delete “{profile.name}” and all its worlds?</span>
73	                <div className="menu-confirm-actions">
74	                  <button
75	                    className="mc-button danger"
76	                    onClick={() => {
77	                      deleteWorldsForProfile(profile.id);
78	                      deleteProfile(profile.id);
79	                      setConfirmingDeleteId(null); // re-render re-reads the manifest
80	                    }}
81	                  >
82	                    Delete
83	                  </button>
84	                  <button className="mc-button" onClick={() => setConfirmingDeleteId(null)}>
85	                    Cancel
86	                  </button>
87	                </div>
88	              </div>
89	            ) : (
90	              <>
91	                <button className="menu-card-play" data-testid={`profile-${profile.id}`} onClick={() => onPlay(profile.id)}>
92	                  <PixelImg src={skinPortraitUrl(profile.skinId)} alt="" size={40} aria-hidden />
93	                  <span className="menu-card-name">{profile.name}</span>
94	                  <span className="menu-card-sub">{worldsForProfile(profile.id).length} worlds</span>
95	                </button>
96	                <div className="menu-card-actions">
97	                  <button
98	                    className="mc-button"
99	                    onClick={() => {
100	                      setEditName(profile.name);
101	                      setEditingId(profile.id);
102	                    }}
103	                  >
104	                    Rename
105	                  </button>
