105	describe("world content balance", () => {
106	  // These floors pin the world's playability, not its exact bytes: they catch
107	  // the degenerate-biome regression class (a whole map collapsing to 1-2
108	  // biomes left some worlds nearly woodless) and survive legitimate
109	  // re-baselines as long as the world still plays right.
110	  test(
111	    "every biome appears with real coverage on the seed-1337 map",
112	    () => {
113	      const world = fullWorld();
114	      const counts = new Map<BiomeId, number>();
115	      let samples = 0;
116	      for (let x = 0; x < world.sizeX; x += 4) {
117	        for (let z = 0; z < world.sizeZ; z += 4) {
118	          const biome = world.getBiome(x, z);
